k='z';E=lambda a,b=None:ev(k,a,b);F=lambda s,a,b,kind='inference':finding(k,s,a,b,kind)
rows=[(286,'萧御打断碎蛋者却遭天龙狂龙合杀，死前见凤凰复苏。','援凤目标达成以本人死亡为代价，并未独力击败公会。',15383,15442),(287,'凤凰移走尸体掉装，复活赐羽、祝福与荣誉；敌方隐匿牧师也能复活同伴。','获三次涅槃和常驻回血；敌队并未永久失去装备。',15443,15493),(288,'钥匙、暗月、星空三人配合追踪；萧御以风速药和黑龙驹脱离。','选择逃走而非击杀三人，继续战场游猎。',15494,15543),(289,'扬刀诱三人出开阔地，以姿态和抗控针对冰法等。','主角旁观识别另一职业的实战规则。',15544,15604),(290,'扬刀靠抗寒和虚招击杀三敌，萧御认出黑赛名单人物。','扬刀显示独立实力，而非主角附庸。',15605,15667),(291,'萧御以高能裂爆杀冰法、术士，拒绝扬刀结交，后杀六敌留同盟装备。','自认救人只是顺带；仍保留不捡友方装备的边界。',15668,15772),(292,'由玩家与NPC血迹持续差异追踪伤者，中途被嘲讽而只杀牧师即走。','线索来自规则差异；情绪反击没有替代原目标。',15773,15833),(293,'遇断右臂重伤盗贼卡尔，风险评估后攻击；速度压迫使喝药困难。','更强对手迫使复用蜗牛与刺刀技巧，并承认能力上限。',15834,15904),(294,'伤肌肉强转身争到喝药窗口，无法追逃后把NPC引入同盟陌生队。','生存选择把危害转嫁别人，不宜净化成无代价机智。',15905,15964),(295,'NPC杀多人，卫风独自殿后，萧御趁其吸引注意控制NPC。','原求战利品的介入，被卫风的担当改变相处方式。',15965,16031),(296,'卫风先逃又回，萧御指导斩杀击败回血NPC，卫风让出掉落。队友返场抢宝。','协作击杀无荣耀却得钥匙，队友贪欲造成新冲突。',16032,16157),(297,'卫风与旧队决裂，萧御以六名敌人为实战讲解战士技巧。','退出旧队后与萧御组队，授艺有基础技能和领悟前提。',16158,16215),(298,'卫风学会冷静抗控、压制和卡时斩杀，连续击杀旧队成员。','能力由当场行动展示，主角要求技巧不外传。',16216,16257),(299,'卫风独胜熟悉自己的卫凌，双方分开；萧御查得隐月之钥可开五级内箱。','一次授艺没有自动建立永久队伍，钥匙用途仍待实际兑现。',16258,16306)]
units=[unit(k,*r) for r in rows]
d={'worldbuilding':[F('凤凰之羽随身生效：元素好感、火抗与火法加成；五分钟后复活及短时增幅只有三次。永久祝福另为回血，不可合成无限复活。',15467,15480,'fact')], 'characters':[F('卫风先为旧友殿后，再为原则与其决裂，又在离开危险后返身支援；可信任性由三次有代价的行动成立。',16066,16124)], 'plot':[F('重伤NPC本应是取宝目标，逃生转嫁危害产生卫风遇险，救援协作后引来旧队分赃冲突，把一条遭遇战发展为人物转折。',15941,15964)], 'style':[F('授艺同时穿插敌人被击杀、技能时机与反应，教程以战斗作示范，代价是连续说理使对手趋于展示材料。',16188,16213)], 'narrative':[F('卫风以为萧御控制链尚有余力，读者已知其快用尽；同一局势下的敬佩与焦虑来自知识落差。',16035,16058)], 'dialogue':[F('卫凌用旧交情求情，卫风以此前行为检验这句话；价值立场通过有具体利益后果的拒绝落实。',16260,16269)], 'pacing':[F('凤凰惨死与获救后插入旁观扬刀，先放缓主角行动再以卡尔追击重启危机；取宝成功后又用分赃制造人际余波。',15443,15543)], 'themes':[F('萧御曾把卡尔引向陌生人造成死亡，后因卫风信义而帮他，文本两行为并存；不能仅摘后段称主角一贯无私救人。',15941,16031)], 'continuity':[F('卡尔右臂已断却一处称右手持匕首；后有卡尔/阿尔变体。凤凰感谢称男爵而系统已子爵；保留原文差异，不自动修补。',15834,15883)]}
c=[{'key':'weifeng','name':'卫风','aliases':[],'summary':'二十六七岁兽人战士，殿后、返援和决裂体现信义，学战术后开始独行。','goals':['保护队友','守原则','改善单练实力'],'changes':['因抢宝事件离队','在指导下连续击败四旧队员','承诺不传授所得技巧'],'relationships':['萧御暂为普通朋友兼指导者','卫凌等旧队员成敌'],'knowledge':['以为萧御能长期控NPC，读者知其极限已近'],'source_anomalies':[],'evidence':E(16027,16124)+E(16159,16177)+E(16289,16296)}, {'key':'xiaoyu','name':'萧御','aliases':[],'summary':'援凤死亡后受救，以冒险逐利引来卫风支线，认可原则而有限授艺。','goals':['战场获益','保持独行自由'],'changes':['凤凰之羽三次复活及永久回血','获得隐月之钥','形成新的战士技战术理解'],'relationships':['风野仍资源合作关系','欣赏卫风但不带永久队友'],'knowledge':['钥匙用途仅属性已知，尚未开锁兑现'],'source_anomalies':['卡尔断臂/持刀手叙述矛盾'],'evidence':E(15467,15480)+E(15941,15964)+E(16258,16303)}, {'key':'yangdao','name':'扬刀','aliases':[],'summary':'强兽人战士，以姿态抗控、药剂和虚招杀三人，刺刀朋友兼黑赛选手。','goals':['猎杀敌阵营'],'changes':['与萧御搭话未建立朋友关系'],'relationships':['自认刺刀最强，属人物判断','萧御拒绝握手因未来可能为敌'],'knowledge':['不知萧御全部能力'],'source_anomalies':[],'evidence':E(15605,15664)+E(15717,15732)}, {'key':'tianlong','name':'天龙','aliases':[],'summary':'与狂龙合杀援凤萧御，后因凤凰复活失败，隐匿牧师复活其团队。','goals':['公会资源获取'],'changes':['失去击杀凤凰机会，装备得回'],'relationships':['与狂龙协调封位','虚无牧师提供备份'],'knowledge':['已见萧御阻拦行动但未主动投入追杀'],'source_anomalies':[],'evidence':E(15420,15437)+E(15444,15461)}]
s=[{'key':'phoenix-success-by-death','title':'以本人死亡换援助成功','summary':'萧御只能打断三人，被双高手杀死，却撑到凤凰复活；目标成功与战斗失败分开。','goal':'阻止十秒内碎蛋','obstacle':'五近战与两个高手协调夹击','choice':'冒险显形打断并承受追杀','consequence':'本人死亡，凤凰存活后救回尸体掉装并回报','state_change':'战术败北却完成选定目标，获得有限复活资源','why_it_works':'兑现明确的十秒条件，保留对手真实能力与胜利成本','applicability':'护送、拖延、救援场','failure_mode':'把临时复活奖励抹成永久无死亡后果','evidence':E(15417,15437)+E(15444,15480)}, {'key':'danger-transferred-to-strangers','title':'转嫁危险后被义气改变行动','summary':'主角引NPC害陌生队，再因卫风殿后而回身协作；保留主角起因与后续救援。','goal':'摆脱卡尔并保留获宝机会','obstacle':'自身无法持续控制且对方高速回血','choice':'先借陌生队分担，再协作并教卫风斩杀','consequence':'队伍损失，卫风返援，两人杀NPC并面对队友抢宝','state_change':'逐利遭遇转为有限信任与道德复杂性','why_it_works':'让人物在有瑕疵的起点上作出新选择，因果不被抹去','applicability':'灰度主角与临时盟友','failure_mode':'删去转嫁危害只留下英雄救援会误读人物','evidence':E(15941,16031)+E(16066,16124)}, {'key':'teaching-proved-by-old-rival','title':'让熟悉旧风格的人验证改变','summary':'卫风经授艺后独自打卫凌，旧友的熟悉反成不能适应新打法的负担。','goal':'摆脱旧关系与二流战斗水平','obstacle':'曾七成胜率压制他的冰法旧友','choice':'提前兽神祈祷抗控、退出冰区再卡解除窗口','consequence':'自主取胜并开始独行，主角不再代打','state_change':'教程内容通过独立行动验证而非旁白宣称','why_it_works':'前后可比的对手提供能力改变的证据','applicability':'学习弧与关系决裂同场完成','failure_mode':'照搬即时开悟会忽略技能基础、训练与主角辅助程度','evidence':E(16270,16296)}]
